public class Main {
    static int sum(int[] values) {
        int total = 0;
        for (int i = 0; i < values.length; i++) {
            total = total + values[i];
        }
        return total;
    }
    public static void main(String[] args) {
        int[] values = {1, 2, 3};
        System.out.println(sum(values));
    }
}

